function firstPickOfEachLetter(s: string): string {
  const need = new Set(s).size;
  let best: string | null = null;
  const go = (i: number, cur: string, used: Set<string>) => {
    if (i === s.length) {
      if (cur.length === need && (best === null || cur < best)) best = cur;
      return;
    }
    go(i + 1, cur, used); // skip s[i]
    if (!used.has(s[i])) {
      used.add(s[i]);
      go(i + 1, cur + s[i], used);
      used.delete(s[i]);
    }
  };
  go(0, "", new Set());
  return best!;
}

