function firstPickOfEachLetter(s: string): string {
  let out = "";
  let rest = s;
  while (rest.length > 0) {
    const letters = [...new Set(rest)].sort();
    for (const c of letters) {
      const tail = rest.slice(rest.indexOf(c));
      if (letters.every(x => tail.includes(x))) {
        out += c;
        rest = tail.slice(1).split(c).join("");
        break;
      }
    }
  }
  return out;
}

