class Solution:
    def firstPickOfEachLetter(self, s: str) -> str:
        out = []
        rest = s
        while rest:
            letters = sorted(set(rest))
            for c in letters:
                tail = rest[rest.index(c):]
                if all(x in tail for x in letters):
                    out.append(c)
                    rest = tail[1:].replace(c, "")
                    break
        return "".join(out)

